import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()) })
await page.goto('http://localhost:8000', { waitUntil: 'load' })
await page.waitForTimeout(900)
await page.click('#startMapBtn').catch(async () => { await page.click('#chooseMapBtn') })
await page.waitForTimeout(500)
await page.click('[data-map=hoth]')
await page.waitForTimeout(300)
await page.click('#mapDockPlayBtn')
await page.waitForTimeout(1200)

const setup = await page.evaluate(() => {
  const g = window.__game
  g.credits = 100000
  const pts = g.pathPts
  const types = ['bounty', 'laser', 'rocket', 'ion', 'scout', 'jedi']
  const placed = []
  const angleSteps = [0, 0.4, -0.4, 0.8, -0.8, 1.2, -1.2, 1.6, -1.6, 2.0, -2.0, 2.4, -2.4, 2.8, -2.8, Math.PI]
  for (let i = 1; i < pts.length - 1 && placed.length < 22; i++) {
    for (const frac of [0.25, 0.5, 0.75]) {
      if (placed.length >= 22) break
      const a = pts[i], b = pts[i + 1]
      const px = a[0] + (b[0] - a[0]) * frac
      const py = a[1] + (b[1] - a[1]) * frac
      const type = types[placed.length % types.length]
      let done = false
      for (const dist of [62, 82, 104, 128, 152]) {
        for (const ang of angleSteps) {
          const x = px + Math.cos(ang) * dist * g.S
          const y = py + Math.sin(ang) * dist * g.S
          if (x < 30 || x > g.w - 30 || y < 60 || y > g.h - 30) continue
          if (g.towers.some(t => Math.hypot(t.x - x, t.y - y) < 52 * g.S)) continue
          const r = g.placeTower(type, x / g.w, y / g.h)
          if (r.ok) {
            const t = r.tower
            g.selected = t
            for (let k = 0; k < 3; k++) g.upgradeSelected()
            g.selected = null
            placed.push({ type, x: +(x).toFixed(0), y: +(y).toFixed(0), level: t.level })
            done = true
            break
          }
        }
        if (done) break
      }
    }
  }
  return { placed, credits: Math.round(g.credits), lives: g.lives, towers: g.towers.length }
})
console.log('SETUP', JSON.stringify(setup))
await page.waitForTimeout(300)
await page.screenshot({ path: 'screenshots/hoth-defense-v2.jpg', type: 'jpeg', quality: 92 })

const run = await page.evaluate(() => {
  const g = window.__game
  g.speed = 8
  const log = []
  let guard = 0
  g.startWave()
  while (g.phase !== 'victory' && g.phase !== 'defeat' && guard++ < 12000) {
    if (!g.waveActive && g.phase === 'build') {
      log.push({ cleared: g.waveNumber - 1, lives: g.lives, kills: g.kills, credits: Math.round(g.credits) })
      g.startWave()
    }
    g.update(0.15)
  }
  log.push({ wave: g.waveNumber, lives: g.lives, kills: g.kills, phase: g.phase, guard })
  return log
})
console.log('RUN', JSON.stringify(run))
await page.waitForTimeout(900)
const end = await page.evaluate(() => {
  const g = window.__game
  const screen = document.querySelector('#endScreen') || document.querySelector('.end-screen')
  return {
    phase: g.phase,
    lives: g.lives,
    waveNumber: g.waveNumber,
    kills: g.kills,
    towers: g.towers.length,
    endVisible: screen ? !screen.classList.contains('hidden') : null,
    endText: screen ? screen.innerText.slice(0, 260) : null,
  }
})
console.log('END', JSON.stringify(end))
await page.screenshot({ path: 'screenshots/hoth-result-v2.jpg', type: 'jpeg', quality: 92 })
console.log('ERRORS', JSON.stringify(errors))
await browser.close()

