  await page.click('#startMapBtn').catch(async () => { await page.click('#chooseMapBtn') })
  await page.waitForTimeout(250)
  await page.click(`[data-map=${id}]`)
  await page.waitForTimeout(250)
  await page.click('#mapDockPlayBtn')
  await page.waitForTimeout(900)
  const state = await page.evaluate(() => {
    const g = window.__game
    return { map: g.map.id, phase: g.phase, started: g.started, towers: g.towers.length, lives: g.lives, credits: g.credits }
  })
  await page.evaluate(() => window.__game.startWave())
  await page.waitForTimeout(1200)
  const wave = await page.evaluate(() => {
    const g = window.__game
    return { wave: g.waveNumber, active: g.waveActive, enemies: g.enemies.length }
  })
  console.log(id, JSON.stringify({ ...state, ...wave }))
  await page.evaluate(() => { const g = window.__game; g.enemies = []; g.waveActive = false; g.spawnQueue = null; g.phase = 'build'; g.quitToMap?.() })
  await page.waitForTimeout(300)
}
console.log('ERRORS', JSON.stringify(errors))
await browser.close()

