import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch(config.browser.launchOptions)
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR', e.message) })
await page.goto('http://localhost:8000', { waitUntil: 'load' })
await page.waitForTimeout(800)
await page.click('#startMapBtn').catch(async () => { await page.click('#chooseMapBtn') })
await page.waitForTimeout(300)
await page.click('[data-map=hoth]')
await page.waitForTimeout(300)
await page.click('#mapDockPlayBtn')
await page.waitForTimeout(1200)

const result = await page.evaluate(() => {
  const g = window.__game
  g.speed = 8
  const pts = g.pathPts
  const typeOrder = ['scout', 'scout', 'ion', 'rocket', 'laser', 'bounty']
  let typeIdx = 0
  const angles = [0, 0.5, -0.5, 1.0, -1.0, 1.5, -1.5, 2.0, -2.0, 2.6, -2.6, Math.PI]
  function tryPlace(type) {
    for (let pass = 0; pass < 2; pass++) {
      for (let i = 1; i < pts.length - 1; i++) {
        for (const frac of [0.3, 0.65, 0.9]) {
          const a = pts[i], b = pts[i + 1]
          const px = a[0] + (b[0] - a[0]) * frac
          const py = a[1] + (b[1] - a[1]) * frac
          for (const dist of [66, 90, 118, 146]) {
            for (const ang of angles) {
              const x = px + Math.cos(ang) * dist * g.S
              const y = py + Math.sin(ang) * dist * g.S
              if (x < 30 || x > g.w - 30 || y < 60 || y > g.h - 30) continue
              if (g.towers.some(t => Math.hypot(t.x - x, t.y - y) < 56 * g.S)) continue
              const r = g.placeTower(type, x / g.w, y / g.h)
              if (r.ok) return r.tower
            }
          }
        }
      }
      if (pass === 0) {
        // Allow tighter spacing on the second pass only if no spot was found.
      }
    }
    return null
  }
  function spend() {
    let guard = 0
    while (guard++ < 12) {
      // Keep adding coverage up to 10 towers, then upgrade the cheapest tower.
      if (g.towers.length < 10) {
        const type = typeOrder[Math.min(typeIdx, typeOrder.length - 1)]
        const t = tryPlace(type)
        if (t) { typeIdx++; continue }
      }
      let best = null
      let bestCost = Infinity
      for (const t of g.towers) {
        if (t.level >= 4) continue
        const cost = [0, 80, 145, 250][t.level] || 9999
        const real = t.type === 'scout' ? [0, 80, 145, 250][t.level]
          : t.type === 'ion' ? [0, 120, 195, 320][t.level]
          : t.type === 'rocket' ? [0, 180, 295, 470][t.level]
          : t.type === 'laser' ? [0, 260, 420, 650][t.level]
          : t.type === 'bounty' ? [0, 450, 690, 1020][t.level] : 9999
        if (real < bestCost) { bestCost = real; best = t }
      }
      if (!best || g.credits < bestCost) break
      g.selected = best
      const r = g.upgradeSelected()
      g.selected = null
      if (!r.ok) break
    }
  }

  spend()
  const log = []
  let guard = 0
  g.startWave()
  while (g.phase !== 'victory' && g.phase !== 'defeat' && guard++ < 20000) {
    if (!g.waveActive && g.phase === 'build') {
      log.push({ wave: g.waveNumber, lives: g.lives, kills: g.kills, credits: Math.round(g.credits), towers: g.towers.length })
      spend()
      g.startWave()
    }
    g.update(0.15)
  }
  log.push({ wave: g.waveNumber, lives: g.lives, kills: g.kills, phase: g.phase, towers: g.towers.length, levels: g.towers.map(t => t.level), types: g.towers.map(t => t.type) })
  return log
})
console.log('BALANCE', JSON.stringify(result))
await page.waitForTimeout(800)
await page.screenshot({ path: 'screenshots/hoth-balance.jpg', type: 'jpeg', quality: 92 })
console.log('ERRORS', JSON.stringify(errors))
await browser.close()

